export const DECK_SIZE = cards.length;
export const CARD_POINTS = 10;
export const COMPLETION_BONUS = 50;
export const STORAGE_KEY = 'lrd-v1';
export const blank = () => ({version:2,personal:null,owned:[],bonus:false,legacyBonus:0});
export function restore(saved){
 const state=blank();
 if(!saved || !Array.isArray(saved.owned))return state;
 state.owned=[...new Set(saved.owned.filter(id=>cards.some(c=>c.id===id)))];
 state.personal=cards.some(c=>c.id===saved.personal)?saved.personal:null;
 if(state.personal&&!state.owned.includes(state.personal))state.owned.push(state.personal);
 state.bonus=state.owned.length===DECK_SIZE;
 // Preserve the award already earned by people who completed the starter deck.
 state.legacyBonus=saved.version===2
  ? (saved.legacyBonus===COMPLETION_BONUS?COMPLETION_BONUS:0)
  : (saved.bonus===true&&cards.slice(0,6).every(c=>state.owned.includes(c.id))?COMPLETION_BONUS:0);
 return state;
}
export function acquire(state,id){
 if(!cards.some(c=>c.id===id)) throw new Error('Unknown card');
 if(state.owned.includes(id)) return {state,award:0,duplicate:true};
 const owned=[...state.owned,id], bonus=owned.length===DECK_SIZE&&!state.bonus;
 return {state:{...state,owned,bonus:state.bonus||bonus},award:CARD_POINTS+(bonus?COMPLETION_BONUS:0),duplicate:false};
}
export const points = state => state.owned.length*CARD_POINTS+(state.bonus?COMPLETION_BONUS:0)+(state.legacyBonus||0);
export function match(answers){
 if(answers.length!==3||answers.some(n=>!Number.isInteger(n)||n<0||n>3))throw new Error('Answer all three questions.');
 // Positional base-four encoding makes every card reachable across 64 answer combinations.
 return cards[answers.reduce((code,n)=>code*4+n,0)%DECK_SIZE].id;
}
export function parseCode(input){
 let code=input.trim();
 if (/^https?:\/\//i.test(code)) { try { const url=new URL(code); code=new URLSearchParams(url.hash.slice(1)).get('card')||''; } catch {} }
 const [kind,id,...extra]=code.split(':');
 if(extra.length||!['place','person'].includes(kind)||!cards.some(c=>c.id===id)) throw new Error('That code isn’t part of this deck. Try a demo code below.');
 return {kind,id};
}
